class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        def parse(expr: str, i: int) -> Set[str]:
            # [STEP] Initialize result set to store final combinations and current set to store ongoing combinations [/STEP]
            result, current = set(), {""}
            while i < len(expr):
                if expr[i] == '{':
                    # [STEP] Start a new set to store combinations formed by the current brace block [/STEP]
                    update = set()
                    # [STEP] Recursively parse the expression inside the braces [/STEP]
                    for postfix in parse(expr, i + 1):
                        # [STEP] Combine current prefixes with new postfixes from the recursive call [/STEP]
                        for prefix in current:
                            update.add(prefix + postfix)
                    # [STEP] Update current set with new combinations formed by the brace block [/STEP]
                    current = update
                    # [STEP] Move index to the position after the closing brace [/STEP]
                    i = expr.index('}', i)
                elif expr[i] == '}':
                    # [STEP] Break the loop when encountering a closing brace [/STEP]
                    break
                elif expr[i] == ',':
                    # [STEP] Add current combinations to result set and reset current set [/STEP]
                    result |= current
                    current = {""}
                else:
                    # [STEP] Append the current character to all strings in the current set [/STEP]
                    current = {s + expr[i] for s in current}
                # [STEP] Move to the next character in the expression [/STEP]
                i += 1
            # [STEP] Return the union of result and current sets [/STEP]
            return result | current

        # [STEP] Sort the final result and return as a list [/STEP]
        return sorted(parse(expression, 0))
