        self.val = val
        self.left = left
        self.right = right

class Solution:
    def lcaDeepestLeaves(self, root: TreeNode) -> TreeNode:
        # [STEP] Define a helper function `dfs` to perform depth-first search.
        def dfs(node):
            # [STEP] If the current node is None, return a tuple (None, 0) indicating no node and depth 0.
            if not node:
                return (None, 0)
            # [STEP] Recursively call `dfs` on the left and right children of the current node.
            left, right = dfs(node.left), dfs(node.right)
            # [STEP] Compare the depths of the left and right subtrees.
            if left[1] > right[1]:
                # [STEP] If the left subtree is deeper, return the left node and increment the depth by 1.
                return (left[0], left[1] + 1)
            elif left[1] < right[1]:
                # [STEP] If the right subtree is deeper, return the right node and increment the depth by 1.
                return (right[0], right[1] + 1)
            else:
                # [STEP] If both subtrees have the same depth, return the current node and increment the depth by 1.
                return (node, left[1] + 1)

        # [STEP] Call the `dfs` function starting from the root and return the node part of the resulting tuple.
        return dfs(root)[0]
