from functools import lru_cache

mod = 10**9 + 7

def numOfWays(steps: int, arrLen: int) -> int:
    # [STEP] Define a helper function `dp` with memoization to avoid redundant calculations. [/STEP]
    @lru_cache(None)
    def dp(s, p):
        # [STEP] If the position `p` is out of bounds or if it's impossible to reach position `p` in `s` steps, return 0. [/STEP]
        if p < 0 or p >= arrLen or p > steps - p:
            return 0
        # [STEP] If no steps are left, check if the current position is the starting position (0). [/STEP]
        if s == 0:
            return p == 0
        # [STEP] Recursively calculate the number of ways to reach the current position by moving from the previous step's positions. [/STEP]
        return (dp(s - 1, p - 1) + dp(s - 1, p) + dp(s - 1, p + 1)) % mod

