class MovieRentingSystem:
    def __init__(self, n, entries):
        self.n = n
        self.entries = entries
        self.unrented = defaultdict(list)
        self.rented = []
        self.shop_movie_price = {}

        for shop, movie, price in entries:
            self.unrented[movie].append((price, shop))
            self.shop_movie_price[(shop, movie)] = price

        for movie in self.unrented:
            self.unrented[movie].sort()

    def search(self, movie):
        return [shop for price, shop in self.unrented[movie][:5]]

    def rent(self, shop, movie):
        price = self.shop_movie_price[(shop, movie)]
        self.unrented[movie].remove((price, shop))
        self.rented.append((price, shop, movie))
        self.rented.sort()

    def drop(self, shop, movie):
        price = self.shop_movie_price[(shop, movie)]
        self.rented.remove((price, shop, movie))
        self.unrented[movie].append((price, shop))
        self.unrented[movie].sort()

