class SeatManager:
    def __init__(self, n: int):
        # [STEP] Initialize a list of available seats from 1 to n [/STEP]
        self.available_seats = [i for i in range(1, n + 1)]
        # [STEP] Convert the list into a min-heap to manage seat reservations efficiently [/STEP]
