from collections import deque

class MyStack:

    def __init__(self):
        # [STEP] Initialize two empty deques to simulate the stack using queues. [/STEP]
        self.q1 = deque()
        self.q2 = deque()

    def push(self, x: int) -> None:
        # [STEP] Add the new element to q2. [/STEP]
        self.q2.append(x)
        # [STEP] Move all elements from q1 to q2 to maintain stack order. [/STEP]
        while self.q1:
            self.q2.append(self.q1.popleft())
        # [STEP] Swap the references of q1 and q2. Now q1 contains the new stack order. [/STEP]
        self.q1, self.q2 = self.q2, self.q1

    def pop(self) -> int:
        # [STEP] Remove and return the front element of q1, which is the top of the stack. [/STEP]
        return self.q1.popleft()

    def top(self) -> int:
        # [STEP] Return the front element of q1 without removing it, which is the top of the stack. [/STEP]
        return self.q1[0]

    def empty(self) -> bool:
        # [STEP] Return True if q1 is empty, otherwise False. [/STEP]
        return not self.q1
