def kBigIndices(nums, k):
    n = len(nums)
    left, right = [0] * n, [0] * n

    for i in range(1, n):
        if nums[i] > nums[i - 1]:
            left[i] = left[i - 1] + 1

        j = n - i - 1
        if nums[j] < nums[j + 1]:
            right[j] = right[j + 1] + 1

    return sum(1 for i in range(n) if left[i] >= k and right[i] >= k)
