class Excel:

    def __init__(self, height: int, width: str):
        # [STEP] Initialize the matrix with zeros. The number of columns is determined by the width ('A' to 'width').
        self.mat = [[0] * (ord(width) - ord('A') + 1) for _ in range(height)]
        # [STEP] Initialize a dictionary to store formulas.
        self.formulas = {}

    def set(self, row: int, column: str, val: int) -> None:
        # [STEP] Create a position string for the cell.
        pos = column + str(row)
        # [STEP] If the cell has a formula, remove it from the formulas dictionary.
        if pos in self.formulas:
            del self.formulas[pos]
        # [STEP] Set the value of the cell in the matrix.
        self.mat[row - 1][ord(column) - ord('A')] = val

    def get(self, row: int, column: str) -> int:
        # [STEP] Create a position string for the cell.
        pos = column + str(row)
        # [STEP] If the cell has a formula, compute its value using the sum method.
        if pos in self.formulas:
            return self.sum(row, column, self.formulas[pos])
        # [STEP] Return the value of the cell from the matrix.
        return self.mat[row - 1][ord(column) - ord('A')]

    def sum(self, row: int, column: str, numbers) -> int:
        # [STEP] Initialize the total sum to zero.
        total = 0
        # [STEP] Iterate over the list of numbers or ranges.
        for num in numbers:
            if ':' in num:
