def simplifyPath(path: str) -> str:
    # [STEP] Initialize an empty stack to store the valid path components. [/STEP]
    stack = []

    # [STEP] Split the input path by '/' to get individual components. [/STEP]
    parts = path.split("/")

    # [STEP] Iterate over each component in the split path. [/STEP]
    for part in parts:
        # [STEP] Skip empty components and the current directory ('.'). [/STEP]
        if not part or part == ".":
            continue
        # [STEP] If the component is '..', pop the last element from the stack if it is not empty. [/STEP]
        if part == "..":
            if stack:
                stack.pop()
        # [STEP] Otherwise, push the component onto the stack. [/STEP]
        else:
            stack.append(part)

    # [STEP] Join the components in the stack with '/' and prepend a '/' to form the simplified path. [/STEP]
    return "/" + "/".join(stack)
