    # [STEP] Define a helper function to process backspaces in a string [/STEP]
    def process_backspaces(string):
        # [STEP] Initialize an empty stack to keep track of characters [/STEP]
        stack = []
        # [STEP] Iterate over each character in the string [/STEP]
        for c in string:
            # [STEP] If the character is not a backspace, add it to the stack [/STEP]
            if c != '#':
